package androidx.heifwriter;import android.media.MediaMuxer;import java.io.IOException;import com.hiro.ulike.TimedIo1947;public class HeifWriter {public final MediaMuxer muxer=new MediaMuxer();public int starts,stops,closes;public IOException startFailure;public Exception stopFailure;public long timeout;public void start()throws IOException{starts++;TimedIo1947.bindMuxer(this,muxer);if(startFailure!=null)throw startFailure;}public void stop(long t)throws Exception{stops++;timeout=t;if(stopFailure!=null)throw stopFailure;}public void close(){closes++;}}